  { h: APP_NODES[2], app: true,  n: "官方·海外 appgb.baozimh.com" }
];
var LINE_LABELS = [];
for (var _li = 0; _li < LINE_HOSTS.length; _li++) LINE_LABELS.push(LINE_HOSTS[_li].n);

var AUTO = "自动（测速选优）";
var SMART = "⚡ 智能（站点推荐）";
var CLASSIFY_PATH = "/baozimhapp/classify";
var PROBE_CID = "buxiufanren-wuyiweidao";
var PROBE_DETAIL = "/comic/" + PROBE_CID;
var PROBE_APP = "/baozimhapp/comic/chapter/" + PROBE_CID + "/0_1.html";
var PROBE_WEB = "/comic/chapter/" + PROBE_CID + "/0_1.html";
// 探针故意用会触发 302 调度的漫画，测速才能识别故障节点（用不触发的书会全绿＝假绿灯）
var PROBE_IMG = "/scomic/yirenzhixia-dongmantang/0/0-a1k5/1.jpg";

var GROUP_NAMES = { region: "地区", state: "状态", type: "题材", filter: "首字母" };
// 画质独立成一个框，值为纯档位标记（分类与画质正交，互不冲掉）
