var SCENE_STATIC = ["⚡ 智能（站点推荐）", "地区·国漫#region=cn", "地区·日本#region=jp", "地区·韩国#region=kr", "地区·欧美#region=en", "状态·连载中#state=serial", "状态·已完结#state=pub", "题材·恋爱#type=lianai", "题材·纯爱#type=chunai", "题材·古风#type=gufeng", "题材·异能#type=yineng", "题材·悬疑#type=xuanyi", "题材·剧情#type=juqing", "题材·科幻#type=kehuan", "题材·奇幻#type=qihuan", "题材·玄幻#type=xuanhuan", "题材·穿越#type=chuanyue", "题材·冒险#type=mouxian", "题材·推理#type=tuili", "题材·武侠#type=wuxia", "题材·格斗#type=gedou", "题材·战争#type=zhanzheng", "题材·热血#type=rexie", "题材·搞笑#type=gaoxiao", "题材·大女主#type=danuzhu", "题材·都市#type=dushi", "题材·总裁#type=zongcai", "题材·后宫#type=hougong", "题材·日常#type=richang", "题材·韩漫#type=hanman", "题材·少年#type=shaonian", "题材·其它#type=qita", "首字母·ABCD#filter=ABCD", "首字母·EFGH#filter=EFGH", "首字母·IJKL#filter=IJKL", "首字母·MNOP#filter=MNOP", "首字母·QRST#filter=QRST", "首字母·UVW#filter=UVW", "首字母·XYZ#filter=XYZ", "首字母·0-9#filter=0-9", "组合·国漫·连载中#region=cn&state=serial", "组合·国漫·已完结#region=cn&state=pub", "组合·日本·连载中#region=jp&state=serial", "组合·日本·已完结#region=jp&state=pub", "组合·韩国·连载中#region=kr&state=serial", "组合·韩国·已完结#region=kr&state=pub", "组合·欧美·连载中#region=en&state=serial", "组合·欧美·已完结#region=en&state=pub"];

// ===== 通用工具 =====
function pref(key) {
  var v = "";
  try {
    if (key === "server") v = vars.get("server");
    else if (key === "line") v = vars.get("line");
    else if (key === "imgHost") v = vars.get("imgHost");
    else if (key === "quality") v = vars.get("quality");
    else if (key === "scene") v = vars.get("scene");
    else if (key === "scene_last") v = vars.get("scene_last");
    else if (key === "line_ms") v = vars.get("line_ms");
    else if (key === "cdn_ms") v = vars.get("cdn_ms");
    else if (key === "server_ms") v = vars.get("server_ms");
  } catch (e) {}
  return String(v || "");
}
function vget(k, dflt) { var v = pref(k); return v ? v : (dflt || ""); }
function unesc(s) {
  return String(s == null ? "" : s)
    .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, " ");
}
function strip(s) {
  return unesc(String(s == null ? "" : s).replace(/<[^>]*>/g, "")).replace(/\s+/g, " ").trim();
}
function hdCover(u) {
  var s = String(u || "").replace(/^http:/i, "https:");
  if (!s || /default_cover|nocover/.test(s)) return "";
  return s.replace(/\?.*$/, "") + "?w=800&h=1200&q=100";
}
// 下拉项解析（「中文前缀 + 空格 + 域名」/「自动（…）」/纯 URL 三种形态）
function pickUrl(raw, fallback) {
  var r = String(raw || "").trim();
  if (!r || /^自动/.test(r)) return fallback;
  var sp = r.indexOf(" ");
  var u = (sp > 0 ? r.substring(sp + 1) : r).replace(/\/+$/, "").trim();
  if (!/^https?:\/\//i.test(u)) u = "https://" + u;
  return u;
}
function labelByHost(pool, labels, url) {
  for (var i = 0; i < pool.length; i++) if (pool[i] === url) return labels[i] || url;
  return url;
}

// 历史耗时：显式列出三个隐藏键，让静态自检能看到消费端（动态 key 无法静态解析）。
// URL 自带 https: ，必须用 lastIndexOf 拆最后一段，split(":") 会切成 3 段恒不命中。
function msTextOf(key) {
  if (key === "line_ms") return String(vars.get("line_ms") || "");
  if (key === "cdn_ms") return String(vars.get("cdn_ms") || "");
  return String(vars.get("server_ms") || "");
}
function msRank(host, key) {
  var raw = msTextOf(key), parts = raw ? raw.split(",") : [], j;
  for (j = 0; j < parts.length; j++) {
    var p = parts[j].lastIndexOf(":");
    if (p > 0 && parts[j].slice(0, p) === host) return parseInt(parts[j].slice(p + 1), 10) || 1e9;
  }
  return 1e9;
}

// ===== 当前线路（全自动：显式 > 最近成功 > 历史最快 > 池首）=====
var LAST_OK = { browse: "", app: "", line: "", cdn: "" };
function curBrowse() { return pickUrl(vget("server", ""), BROWSE[0]); }
function curCdn() {
  var c = vget("imgHost", "");
  if (!c || /^自动/.test(c)) return "";
  return pickUrl(c, "");
}
function curLine() { return pickUrl(vget("line", ""), ""); }

function rankPool(pool, key, first) {
  var f = first || pool[0], order = [f], seen = {}, rest = [], i;
  seen[f] = 1;
  for (i = 0; i < pool.length; i++) if (!seen[pool[i]]) rest.push(pool[i]);
  rest.sort(function (a, b) { return msRank(a, key) - msRank(b, key); });
  return order.concat(rest);
}
function hostOrder() { return rankPool(BROWSE, "server_ms", LAST_OK.browse || curBrowse()); }
function appOrder() { return rankPool(APP_NODES, "line_ms", LAST_OK.app); }
function lineOrder() {
  var cur = curLine(), first = null, i;
  if (cur) for (i = 0; i < LINE_HOSTS.length; i++) if (LINE_HOSTS[i].h === cur) { first = LINE_HOSTS[i]; break; }
  var rest = [], seen = {};
  if (first) seen[first.h] = 1;
  for (i = 0; i < LINE_HOSTS.length; i++) if (!seen[LINE_HOSTS[i].h]) rest.push(LINE_HOSTS[i]);
  // 自动模式保持定义顺序：网页线优先且第一条即命中，不会触碰不可达的备用节点。
  // 仅用户显式选线时，才按历史耗时对其余线路排序（测速切换仍有意义）。
  if (first) rest.sort(function (a, b) { return msRank(a.h, "line_ms") - msRank(b.h, "line_ms"); });
  // 自动模式：优先用本次运行里上次成功的线路（原来忽略它，导致每章都先撞超时的第一条线）
  if (!first && LAST_OK.line) {
    for (var k2 = 0; k2 < rest.length; k2++) {
      if (rest[k2].h === LAST_OK.line) { var hit2 = rest.splice(k2, 1)[0]; rest.unshift(hit2); break; }
    }
  }
  return (first ? [first] : []).concat(rest);
}
function qPath() {
  var q = String(vget("quality", "高清 w800") || "");
  if (q.indexOf("w640") >= 0) return "/w640";
  if (q.indexOf("w800") >= 0) return "/w800";
  return "";   // 原图
}
// 图片地址统一改写到直出节点：章节页给的是裸 host，部分漫画会被 302 调度到故障节点，
// 导致真机「章节页能取到、图片全裂」。默认用池首，用户显式选线时优先其选择，
// 自动模式按历史耗时排序；画质档位仍插在 host 之后。
function cdnOrder() { return rankPool(IMGCDN, "cdn_ms", LAST_OK.cdn || ""); }
function mapCdn(list) {
  var cdn = curCdn(), q = qPath(), out = [], i;
  var fallback = cdn || cdnOrder()[0];
  var host = fallback.replace(/^https?:\/\//, "").replace(/\/$/, "");
  for (i = 0; i < list.length; i++) {
    var mm = /^https?:\/\/([^\/]+)(\/.*)$/.exec(String(list[i]));
    if (!mm) { out.push(list[i]); continue; }
    out.push("https://" + host + q + mm[2]);
  }
  return out;
}

// ===== 请求层 =====
function reqHeaders(h, app) {
  return { "User-Agent": app ? APPUA : UA, "Referer": h + "/", "Accept-Language": LANG };
}
// 搜索 / 详情 / 目录：逐条降级，命中只记内存，不改用户设置
function browseGet(path) {
  var order = hostOrder(), fails = [], i;
  for (i = 0; i < order.length; i++) {
    var h = order[i];
    try {
      var r = http.get(h + path, { headers: reqHeaders(h, false), timeout: 8000 });
      if (r && r.ok && r.body && String(r.body).length > 200) {
        LAST_OK.browse = h;
        return String(r.body);
      }
      fails.push(h.replace(/^https?:\/\//, "") + "=" + (r && r.status ? r.status : "空"));
    } catch (e) { fails.push(h.replace(/^https?:\/\//, "") + "=err"); }
  }
  throw new Error("浏览线路全不通：" + fails.join(" "));
}
// 分类页：三个站点自有节点逐条降级
function appGet(path) {
  var order = appOrder(), fails = [], i;
  for (i = 0; i < order.length; i++) {
    var h = order[i];
    try {
      var r = http.get(h + path, { headers: reqHeaders(h, true), timeout: 8000 });
      if (r && r.ok && r.body && String(r.body).length > 200) {
        LAST_OK.app = h;
        return String(r.body);
      }
      fails.push(h.replace(/^https?:\/\//, "") + "=" + (r && r.status ? r.status : "空"));
    } catch (e) { fails.push(h.replace(/^https?:\/\//, "") + "=err"); }
  }
  throw new Error("分类线路全不通：" + fails.join(" "));
}

// 分类取数双通道：浏览线 /classify 首选（与搜索/详情同线路），站点自有节点备用。
// 两条通道共用同一套筛选参数，返回来源让上层选对应解析器；
// 单组节点不可达时自动降级，不再因取数失败让发现页整体报错。
function classifyHtml(q) {
  var q2 = normQuery(q), i;
  try {
    var h = browseGet(classifyPath(q2));
    if (h && h.length > 200) return { html: h, fromApp: false };
  } catch (e) {}
  var order = appOrder();
  for (i = 0; i < order.length; i++) {
    try {
      var r = http.get(order[i] + appPath(q2), { headers: reqHeaders(order[i], true) });
      if (r && r.ok && r.body && String(r.body).length > 200) {
        LAST_OK.app = order[i];
        return { html: String(r.body), fromApp: true };
      }
    } catch (e2) {}
  }
  return { html: "", fromApp: false };
}
// 按来源选用解析器：官方节点页用 appCards，浏览线页用 cards
function classOf(c) { return c.fromApp ? appCards(c.html) : cards(c.html); }

// ===== 解析层 =====
// 网页线卡片：<div class="comics-card ..."> + href="/comic/<cid>"
function cards(html) {
  var out = [], parts = String(html || "").split(/<div\s+class="comics-card[\s"]/), i;
  for (i = 1; i < parts.length; i++) {
    var seg = parts[i];
    var hm = /href="\/comic\/([^"?#&]+)/.exec(seg);
    if (!hm) continue;
    var cid = hm[1];
    var nm = /<h3[^>]*>([\s\S]*?)<\/h3>/.exec(seg);
    var au = /<small[^>]*class="[^"]*tags[^"]*"[^>]*>([\s\S]*?)<\/small>/.exec(seg);
    var tm = /title="([^"]+)"/.exec(seg);
    var name = strip(nm ? nm[1] : "") || strip(tm ? tm[1] : "");
    if (!name || !cid) continue;
    var im = null, ims = seg.match(/(?:amp-img|img)[^>]*\ssrc="(https:\/\/[^"]+\/cover\/[^"]+)"/g) || [], k;
    for (k = 0; k < ims.length; k++) {
      var sm = /src="([^"]+)"/.exec(ims[k]);
      if (sm && !/default_cover|nocover/.test(sm[1])) { im = sm; break; }
    }
    var tags = [], tab, tre = /<span[^>]*class="[^"]*\btab\b[^"]*"[^>]*>([\s\S]*?)<\/span>/g;
    while ((tab = tre.exec(seg)) !== null) {
      var t = strip(tab[1]);
      if (t && tags.indexOf(t) < 0) tags.push(t);
    }
    out.push({
      name: name, author: strip(au ? au[1] : ""), kind: tags.join(" · "),
      intro: "", coverUrl: hdCover(im ? im[1] : ""),
      bookUrl: "bzmh://comic/" + cid, tocUrl: "bzmh://toc/" + cid, type: "comic"
    });
  }
  return out;
}
// 站点分类页卡片：send_app_msg('call_page',['comic',cid]) + data-src 封面 + span.tab 标签
function appCards(html) {
  var out = [], parts = String(html || "").split(/<div\s+class="comics-card[\s"]/), i;
  for (i = 1; i < parts.length; i++) {
    var seg = parts[i];
    var cm = /send_app_msg\('call_page',\s*\['comic',\s*'([^']+)'\]/.exec(seg);
    if (!cm) continue;
    var cid = cm[1];
    var nm = /<h3[^>]*>([\s\S]*?)<\/h3>/.exec(seg);
    var tm = /title="([^"]+)"/.exec(seg);
    var au = /<small[^>]*class="[^"]*tags[^"]*"[^>]*>([\s\S]*?)<\/small>/.exec(seg);
    var name = strip(nm ? nm[1] : "") || strip(tm ? tm[1] : "");
    if (!name) continue;
    var im = /data-src="(https:\/\/[^"]+\/cover\/[^"]+)"/.exec(seg);
    var tags = [], tab, tre = /<span[^>]*class="[^"]*\btab\b[^"]*"[^>]*>([\s\S]*?)<\/span>/g;
    while ((tab = tre.exec(seg)) !== null) {
      var t = strip(tab[1]);
      if (t && tags.indexOf(t) < 0) tags.push(t);
    }
    out.push({
      name: name, author: strip(au ? au[1] : ""), kind: tags.join(" · "),
      intro: "", coverUrl: hdCover(im ? im[1] : ""),
      bookUrl: "bzmh://comic/" + cid, tocUrl: "bzmh://toc/" + cid, type: "comic"
    });
  }
  return out;
}
// 运行时解析站点分类页的筛选项：handle_change_filters(this,'key','val')" class="item...">label</div>
function parseAppFilters(html) {
  var out = [], seen = {}, m;
  var re = /handle_change_filters\(this,\s*'([^']+)',\s*'([^']*)'\)"\s*class="item[^>]*>\s*([^<]+?)\s*<\/div>/g;
  while ((m = re.exec(String(html || ""))) !== null) {
    var k = m[1], v = m[2], label = strip(m[3]);
    if (!GROUP_NAMES[k] || !v || v === "all" || v === "*" || !label) continue;
    var item = GROUP_NAMES[k] + "·" + label + "#" + k + "=" + v;
    if (seen[item]) continue;
    seen[item] = 1;
    out.push(item);
  }
  return out;
}
// 浏览线分类页筛选项：<a href="/classify?type=gufeng&...">古風</a>
// 只取参数值，标签沿用自挖的简体场景表，站点新增值无对应标签则跳过，保证下拉始终简体。
function parseWebFilters(html) {
  var out = [], seen = {}, m, j, kv;
  var re = /<a[^>]*href="([^"]*\/classify\?[^"]*)"[^>]*>[\s\S]*?<\/a>/g;
  while ((m = re.exec(String(html || ""))) !== null) {
    var href = unesc(m[1]), kre = /[?&](type|region|state|filter)=([^&]+)/g;
    while ((kv = kre.exec(href)) !== null) {
      var k = kv[1], v = kv[2];
      if (!v || v === "all" || v === "%2a" || v === "*" || v === "2a") continue;
      for (j = 0; j < SCENE_STATIC.length; j++) {
        var sc = SCENE_STATIC[j];
        if (sc.indexOf("#" + k + "=" + v) > 0 && !seen[sc]) { seen[sc] = 1; out.push(sc); break; }
      }
    }
  }
  return out;
}

// 由「地區 × 狀態」自动派生组合，无需手工枚举
function comboScenes(items) {
  var regs = [], sts = [], out = [], i, j, m, s;
  for (i = 0; i < items.length; i++) {
    m = /^地区·([^#]+)#region=([^&]+)$/.exec(items[i]);
    if (m) regs.push([m[1], m[2]]);
    s = /^状态·([^#]+)#state=([^&]+)$/.exec(items[i]);
    if (s) sts.push([s[1], s[2]]);
  }
